"""Report Generator: validated analysis + retrieved sources -> final structured Report."""
from datetime import datetime, timezone

from app.config import get_settings
from app.schemas.llm import LLMAnalysis
from app.schemas.research import EvidenceSource, Reference, Report
from app.services.citations import validate_analysis
from app.services.modes import ModeConfig
from app.services.planner import ResearchPlan

INSUFFICIENT = "Insufficient evidence found."
MIN_SOURCES_FOR_ANALYSIS = 2

DISCLAIMER = (
    "This report was generated by an AI system from web pages retrieved at the time of the search. "
    "Sources have not been independently verified, appearing in search results does not make a source "
    "credible, and accuracy is not guaranteed. Check the cited sources before relying on any claim."
)


def build_report(
    topic: str,
    plan: ResearchPlan,
    analysis: LLMAnalysis,
    sources: list[EvidenceSource],
    cfg: ModeConfig,
) -> Report:
    v = validate_analysis(analysis, sources)

    limitations = [x for x in v.limitations if x]
    undated = [s.id for s in sources if s.published_date == "Date unavailable"]
    if undated and len(undated) == len(sources):
        limitations.append("No publication dates were available for any retrieved source, so recency could not be assessed.")
    elif undated:
        limitations.append(f"Publication date unavailable for {len(undated)} of {len(sources)} sources ({', '.join(undated)}).")
    if v.report.findings_quote_verified < v.report.findings_total:
        n = v.report.findings_total - v.report.findings_quote_verified
        limitations.append(f"For {n} key finding(s) the quoted evidence could not be located in the cited source text; treat them with extra caution.")

    insufficient = (
        analysis.insufficient_evidence
        or len(sources) < MIN_SOURCES_FOR_ANALYSIS
        or not v.key_findings
    )
    if insufficient and INSUFFICIENT.lower() not in " ".join(limitations).lower():
        limitations.insert(0, INSUFFICIENT)
    if not v.key_findings:
        v.report.notes.append("No key finding survived citation validation.")

    references = [
        Reference(
            id=s.id, title=s.title, url=s.url, domain=s.domain,
            published_date=s.published_date, cited=s.id in v.cited_ids,
        )
        for s in sources
    ]

    return Report(
        title=(analysis.title or topic).strip()[:200],
        objective=(analysis.objective or plan.objective).strip(),
        executive_summary=v.executive_summary or INSUFFICIENT,
        key_findings=v.key_findings,
        detailed_analysis=v.detailed_analysis,
        comparison=v.comparison,
        conflicts=v.conflicts,
        outdated_info=v.outdated_info,
        unsupported_claims=v.unsupported_claims,
        limitations=limitations,
        conclusion=v.conclusion or INSUFFICIENT,
        insufficient_evidence=insufficient,
        references=references,
        citation_report=v.report,
        disclaimer=DISCLAIMER,
        mode=cfg.name,  # type: ignore[arg-type]
        model=get_settings().gemini_model,
        queries=plan.queries,
        generated_at=datetime.now(timezone.utc),
    )
